/**
 * Turn a string into a URL slug: lowercase, runs of non-alphanumerics become a
 * single hyphen, no leading or trailing hyphens.
 *
 * options.maxLength: if set, cut the slug to at most that many characters at a
 * word boundary (last hyphen within the limit). If the first word alone is
 * longer than maxLength, the word itself is cut.
 */
export function slugify(input, options) {
  const slug = String(input)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');

  const maxLength = options && options.maxLength;
  if (maxLength === undefined || maxLength === null || slug.length <= maxLength) {
    return slug;
  }
  if (maxLength <= 0) return '';

  // A word boundary at index maxLength means the first maxLength chars are whole words.
  const cut = slug.lastIndexOf('-', maxLength);
  const result = cut > 0 ? slug.slice(0, cut) : slug.slice(0, maxLength);
  return result.replace(/-+$/g, '');
}

